import React, { useState } from 'react';
import { 
  formatRelativeTime, 
  formatFullDate, 
  calculateReadingTime, 
  getInitials, 
  getAvatarGradient 
} from '../utils/humanize';
import './PostItem.css';

const PostItem = ({ post, onEdit, onDelete }) => {
  const [isExpanded, setIsExpanded] = useState(false);
  const [liked, setLiked] = useState(false);
  const [likesCount, setLikesCount] = useState(() => {
    // Generate an initial random or consistent like count based on post id
    if (!post._id) return 3;
    let sum = 0;
    for (let i = 0; i < post._id.length; i++) sum += post._id.charCodeAt(i);
    return (sum % 9) + 2;
  });

  const handleLike = () => {
    if (liked) {
      setLiked(false);
      setLikesCount(prev => prev - 1);
    } else {
      setLiked(true);
      setLikesCount(prev => prev + 1);
    }
  };

  const relativeTime = formatRelativeTime(post.publishedDate);
  const fullDate = formatFullDate(post.publishedDate);
  const readingTime = calculateReadingTime(post.content);
  const initials = getInitials(post.author);
  const avatarBg = getAvatarGradient(post.author);
  const isLongContent = post.content && post.content.length > 280;

  return (
    <article className="post-card slide-in" role="listitem">
      <header className="post-card-header">
        <div className="post-author-row">
          <div 
            className="author-avatar" 
            style={{ background: avatarBg }}
            title={post.author}
            aria-hidden="true"
          >
            {initials}
          </div>
          <div className="author-info">
            <span className="post-author-name">{post.author || 'Anonymous'}</span>
            <div className="post-meta-sub">
              <time className="post-relative-time" title={fullDate} dateTime={post.publishedDate}>
                {relativeTime}
              </time>
              <span className="meta-dot">·</span>
              <span className="post-reading-pill" title="Estimated reading time">
                ☕ {readingTime}
              </span>
            </div>
          </div>
        </div>

        <h3 className="post-card-title">{post.title}</h3>
      </header>

      <div className={`post-card-content ${isExpanded ? 'expanded' : ''}`}>
        <p>{post.content}</p>
        {isLongContent && (
          <button 
            type="button" 
            className="btn-read-more" 
            onClick={() => setIsExpanded(!isExpanded)}
          >
            {isExpanded ? 'Show less ↑' : 'Read full story ↓'}
          </button>
        )}
      </div>

      <footer className="post-card-footer">
        <button
          type="button"
          className={`btn-reaction ${liked ? 'active' : ''}`}
          onClick={handleLike}
          aria-label={liked ? 'Unlike this story' : 'Applaud this story'}
          title={liked ? 'You liked this' : 'Applaud story'}
        >
          <span className="reaction-icon">{liked ? '❤️' : '🤍'}</span>
          <span className="reaction-count">{likesCount}</span>
        </button>

        <div className="post-card-actions">
          <button
            type="button"
            className="btn btn-icon"
            onClick={() => onEdit(post)}
            aria-label={`Edit "${post.title}"`}
            title="Edit story"
          >
            <svg width="17" height="17" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" />
            </svg>
          </button>
          <button
            type="button"
            className="btn btn-icon btn-danger-subtle"
            onClick={() => onDelete(post._id)}
            aria-label={`Delete "${post.title}"`}
            title="Delete story"
          >
            <svg width="17" height="17" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
            </svg>
          </button>
        </div>
      </footer>
    </article>
  );
};

export default PostItem;
